mapper.select:
SELECT

FROM SysFrontModule a WHERE 1 = 1 

    AND a.moduleClass = #{moduleClass}


    AND a.moduleCode LIKE CONCAT('%',#{moduleCode}, '%')


    AND a.moduleName LIKE CONCAT('%',#{moduleName}, '%')


    AND a.moduleIconUrl LIKE CONCAT('%',#{moduleIconUrl}, '%')


    AND a.moduleJumpUrl = #{moduleJumpUrl}


    AND a.sortNum = #{sortNum}


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createBy = #{createBy}


    AND a.createDate = #{createDate}


    AND a.updateBy = #{updateBy}


    AND a.updateDate = #{updateDate}


    AND a.updateDate = #{updateDate}

SELECT  FROM SysFrontModule a
left join FrontRoleRes b on a.id = b.moduleId
WHERE b.roleId = #{roleId}
